package com.digitaloffice.document;
import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import java.nio.charset.StandardCharsets; import java.util.*;
@RestController @RequestMapping("/api/v1/documents/{docId}/activity") public class DocumentActivityController {
 private final DocumentRepository documents; private final DocumentVersionRepository versions; private final DocumentActivityService activity; private final OrganizationMembershipClient memberships; private final ProjectParticipationClient participations;
 public DocumentActivityController(DocumentRepository d,DocumentVersionRepository v,DocumentActivityService a,OrganizationMembershipClient m,ProjectParticipationClient p){documents=d;versions=v;activity=a;memberships=m;participations=p;}
 @GetMapping public List<DocumentActivityEvent> list(@PathVariable UUID docId,@AuthenticationPrincipal Jwt jwt,@RequestHeader("Authorization") String token){Document d=documents.findById(docId).orElseThrow(()->new NoSuchElementException("Document not found"));UUID actor=UUID.nameUUIDFromBytes(("oidc:"+jwt.getSubject()).getBytes(StandardCharsets.UTF_8));boolean allowed=memberships.getActiveMemberships(actor,token).stream().anyMatch(m->participations.hasActiveParticipation(d.getProjectId(),m.organizationId(),token));if(!allowed)throw new org.springframework.security.access.AccessDeniedException("Actor cannot access document activity");Set<UUID> versionIds=versions.findByDocumentIdOrderByVersionNumberAsc(docId).stream().map(DocumentVersion::getId).collect(java.util.stream.Collectors.toSet());return activity.byProject(d.getProjectId()).stream().filter(e->versionIds.contains(e.getSubjectId())).toList();}
}
